def generateParenthesis(self, n: int) -> list[str]:
    from itertools import product

    def is_valid(s: str) -> bool:
        bal = 0
        for c in s:
            bal += 1 if c == '(' else -1
            if bal < 0:
                return False
        return bal == 0

    result = []
    for combo in product('()', repeat=2 * n):
        s = ''.join(combo)
        if is_valid(s):
            result.append(s)
    return result

